const items = $input.all();
const outputs = [];
const debugInfo = []; // Array de salvamento para debug

for (const item of items) {
  const input = item.json;

  // Captura todas as colunas que vieram do Sheets para visualizarmos
  const chavesDisponiveis = Object.keys(input);

  // Busca dinâmica pelo e-mail (ignora maiúsculas/minúsculas e procura partes da palavra)
  let emailRaw = null;
  for (const key of chavesDisponiveis) {
    const keyLower = key.toLowerCase();
    if (keyLower.includes('e-mail') || keyLower.includes('email') || keyLower.includes('corporativo')) {
      emailRaw = input[key];
      break; // Achou a coluna, para de procurar
    }
  }
  const email = emailRaw ? emailRaw.toString().trim() : null;

  const palpites = [];

  // Regex atualizada: Aceita possíveis espaços em branco ANTES do colchete
  const questionRegex = /^\s*\[(\d+)\]/;

  for (const key in input) {
    const match = key.match(questionRegex);

    if (match && input[key]) {
      const gameId = parseInt(match[1]);
      const placarRaw = input[key].toString().toLowerCase().trim();
      const partes = placarRaw.split('x');

      if (partes.length === 2) {
        palpites.push({
          jogoId: gameId,                        // <-- O nome exato que o seu Node espera!
          palpiteA: parseInt(partes[0].trim()),
          palpiteB: parseInt(partes[1].trim())
        });
      }
    }
  }

  if (email && palpites.length > 0) {
    outputs.push({
      json: {
        email: email,
        palpites: palpites
      }
    });
  } else {
    // Se a linha falhar, documenta o porquê
    debugInfo.push({
      json: {
        status: "FALHA DE EXTRAÇÃO",
        motivo: !email ? "E-mail não detectado" : "Regex de jogos falhou (Nenhum palpite capturado)",
        emailEncontrado: email,
        quantidadePalpites: palpites.length,
        chavesRecebidasDaPlanilha: chavesDisponiveis,
        dadosBrutos: input
      }
    });
  }
}

// Se deu tudo certo, retorna o payload final. Se falhou, retorna o log de erro.
return outputs.length > 0 ? outputs : debugInfo;
